import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"易纬乾元序制记〔汉〕郑玄","description":"易纬乾元序制记 - 易纬乾元序制记〔汉〕郑玄","frontmatter":{"title":"易纬乾元序制记〔汉〕郑玄","description":"易纬乾元序制记 - 易纬乾元序制记〔汉〕郑玄"},"headers":[],"relativePath":"zh/classics/yiwei-qianyuan/001.md","filePath":"zh/classics/yiwei-qianyuan/001.md"}'),r={name:"zh/classics/yiwei-qianyuan/001.md"};function c(o,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易纬乾元序制记〔汉〕郑玄",tabindex:"-1"},[n("易纬乾元序制记〔汉〕郑玄 "),e("a",{class:"header-anchor",href:"#易纬乾元序制记〔汉〕郑玄","aria-label":"Permalink to “易纬乾元序制记〔汉〕郑玄”"},"​")],-1),e("p",null,"钦定四库全书易纬乾元序制记 ​汉 郑康成 注乾：元、亨、利、贞，道之用也。微明所接，德由备也。 ​道之用者，道之所起也备。乾为天，天豳微萌明之，道之所交也。德由是故备，谓经称「元、亨、利、贞」也。文王比隆兴始霸。 ​文王比德于乾之隆盛，谓其龙德长人以善，通其嘉会利贞之义。乾之以正，始霸四方，被江汉之上。伐崇，作灵台，受赤雀丹书，称王制命，示王意。 ​入戊午蔀二十九年，时有赤雀衔丹书而授之。郑按：诗文王萹孔颖达正义引此文作是类谋，又引注称 康成，今故据以为康成所注。又上文「兴始霸」原本作「兴起霸」，今亦据正义文改。序录著卦科合谋 ​序录，序王录。著卦为六十四卦经科，设王令之卦。言道。深微幽虚恢。 ​深微幽虚，言纯精无形。恢，大也。乾一言𫄙图侯 ​此一言乾一守。𫄙犹正。侯，要终也。误。按此注疑有脱。神烂天地塞， ​塞，满。言乾之神明烂然满天地之间也。文王用其不倦，武发修其质素，周公用其节序，三圣首乾德，各就「乾元利贞」，每遗夕惕若厉，惧后戒。 ​言三圣俱首乾德，而所有同异。「厚」当为亨。文王自朝至于日昃，不遑暇食，是乾乾不倦。武王承而行之，不敢有加，是乾之质素。周公制礼作乐，光文、武之业，是乾之节厚。六长人以善，嘉会通礼，利慎于义，干事能正，六德靡悔，战战兢兢，三圣同之也。 按「节序」，据注应作「节候」。是类摘表甄符，应合命精克慎不合， ​甄绝。三圣俱知天命，能挺兴衰之表象，及瑞之所应合，明天命精微之道，极慎不合道也。钩效纪录，兴亡授度。 ​效，验。言天能钩验五精，记其次第兴亡，天人皆受法度。或为「授」。天子必思易，先知万世，为国著柄。 ​柄，本要也。察之在，失之去。每云天命在主，摽操 ​存在去亡。操行主，王之存亡。天命要，主之所行，用道兴王也。六十四卦，各括精受节，以历纪道。 ​括从絬精受节，谓各用事于诸月，以应纪明。天道，谓寒温之节与藏者也。因象著命，取佐书，以州土之运次衡伍。 ​因象著命，谓叙其世数及名姓。取佐捉下辄皆以州土之运，以之卦于土，各有卦分相当，衡亭行为位之。 按此注疑有脱误。一岁十二月三百六十五日四分度之一。 ​文宜言「四分日之一」。一日行一度，因言度余二十。 ​余，小余，即上「四分度之一」分数。四分一日以为八十分，二十为之。 ​四分一日以为大分则八十，以为小分则二十。小分四为一大分，消息十二月，月居六日七分，十二月居七十三日一百八十分居四分。 ​消息十二月，正居七十二日，通计余分八十日四分，则七十三日八十分之四也。三公十二月，月居六日七分，十二月居七十三日一百八十分居四分。 ​按此下尚应有「九卿」一条，方合五德之数，盖有脱文也。二十七大夫十二月，月居六日七分，十二月居七十三日一百八十分居四分。八百一十二诸侯十二月，月居六日七分，十二月居七十三日一百八十分居四分。合德之分。 ​五德，辟公、卿、大夫、诸侯也。三十日得三十五， ​此则五卦之余分。三十尽十二月，六十卦余分适四百二十分五日四分日一。 ​其法以余分来乘卦，得四百二十，以八十余已，则五日四分日一矣。此则方伯不与余之也矣。辟卦温气不效，六卦阳物不生，土功起。 ​六卦谓泰卦、大壮也。夬、乾、姤也。盛阳时温气不效，故阳物不生，土功起也。○按注「姤」下尚当有「遁」卦，疑脱文。三卦阳气不至，疾伤，日蚀既。 ​三卦谓泰、大壮、夬。此阳气盛息，其候决温，其气不至，故辟忧疾，日蚀既日矣。六卦不至，震水涌。 ​其上三卦不效，后三卦又不效，于是阴乘其阳，故地震水涌也。寒气不效，六卦不至，冬荣实物不成。夏寒伤生，冬温伤成，日月不明，四时失序，万物散去。 ​六卦谓否、观、剥、坤、复、临。盛阴用事，而寒气不效，万物冬荣，实物不成，其冲必有大寒，伤生物者也。辟卦七十三日，日分之四。常风乱先王之法度，常风。 ​常风，每卦用事，有暴风也。○按正文「法度」下「常风」二字疑衍。寒不时，所威不得其人。 ​谓春夏有寒效也。秋不霜，行春令，缓刑罚。冬不冰，行秋令，免有罪。春冻不解， ​亦谓温效于秋初也。必有受命所亡。 ​谓受命之君所诛灭。奢侈过度，刑罚妄行，百姓急不足，困饥作奢。此受命所行， ​言王者虽有际会，安在其行之会？辟杀之法，十二卦常蒙三十六年杀，非受命所亡也。 ​常不清明，非受命所亡。言此君臣自相杀之候。○按「非受命所亡也」应作正文，「常不清明」以下应作注。原本以正文混作注，以注混作正文，今俱订正。卦不至为三年。二卦不至为六年，三卦不至为九年，四卦不至为十二年，五卦不至为十五年，六卦不至为十八年，七卦不至为二十一年，八卦不至为二十四年。九卦不至为二十七年，十卦不至为三十年。十一卦不至为三十三年。十二卦不至为三十六年。 ​不至，谓温不效，乃不清明也。卦始用事，象东风雨，象施于也。 ​按：「于」下疑有脱字。西方至，象作威也。南风，有罪也。 ​按：有罪上当有脱字。北风至，熟无罪也。 ​按：「熟」疑应作「杀」，盖以杀变「煞」而误者。东北为雨，西南为正，东南为温，西北为寒， ​谓始用事也。文按：此注原本混入正， 今订正。用事，东北为雨，西南为正也。东北南西皆风，东南温，西北为寒， ​皆谓用事日也。○按：东北、南西二句，原本混作注，皆谓句混作正文，今俱订正。观六四知其正。此候及四位之人，非独辟之。候卦要法，谨察卦用事日分数，当寒者寒，当暑者暑，当风者风，当雨者雨，此平法。 ​二为升气，五为降气，升阳为阳，升阴马寒，降阳为风，降阴为雨也。谨司六月中寒温风雨，记其日与时，发时以验方来，万全不失一。 ​降效验也。夏升降寒阴三过度，涌水为败。夏升阳降阳，温三过度，降雨为败。 ​谓六三、上六也。当微寒，过故为败也。坎初，冬至，广莫。震初，春分，明庶。离初，夏至景风。兑初，秋分，霜下。卦候到占法 ​此四卦者，始效分至二十四气之主，故候其初用事以占之失。复姓角名宫，赤黄色，长八尺一寸，三十六世。临姓商名宫，黄白色，长八尺三寸一分，七十二世。泰姓商名宫，黄白色，长七尺六寸，三十六世。 ​按隋书王劭传称坤电图云：「泰姓商名宫，黄色，长八尺，六十世。」与此不同。疑此即引坤灵图原文，而传写互异者。大壮，姓商名角，苍白色，长七尺三寸九分，百三十一世。右圣人受命，瑞应之至，圣人杀龙，圣人兴起，河图出之者。 ​按此与上下文不相属，当有错误。据隋书王劭传、马骕绎史引坤灵图文有「圣人受命，瑞应先于河，瑞应之至，圣人杀龙，龙不可杀，皆盛气也」云云，疑即此文，而中有脱落耳。姤，姓角名商，苍白色，长六尺三寸，二十八世。遁，姓宫名商，黄白色，长五尺九寸八分，五十六世。否，姓宫名商，黄白色，长五尺六寸一分，七十二世。观，姓宫名角，苍白色，长五尺三寸二分，百三十世。剥，姓商名宫，黄白色，长五尺九寸九分，百二十世。古君子得众人所助，圣人兴起必乾土，故大人动得中，君子受命法地蛇。 ​圣人兴起必乾土之中者，言必择土中而天下也。此在简柝，预在此章之载。○按毛诗孔疏引坤灵图云：「法地之瑞，黄龙中流见于洛。」又绎史引坤灵图云：「君子得众人之助，瑞应先见于陆。瑞应之至，君子法地，蛇不如龙，陆不如河。」与此文俱相合。疑自「古君子」以下，俱当为【【【坤灵图】】】之文，而中有脱简耳。乾姓商，名商，白色，享国百二十。坤姓商，名宫，黄色，享国百二十。震姓角名，苍色，享国七十二。 ​按「名」下脱一字。巽姓角，名角，苍色，享国六十四。离姓征，名征，赤色，享国六十四。兑姓商，名商，白色，享国六十四。坎姓羽，名羽，黑色，享国七十二。艮名宫，黄色，享国 ​七十二。按艮字下脱去二字。帝者，雒书居处法 ​亦宜有「右」字，以脱耳。○按【居处法】盖亦雒书纬名，以上疑引其词，而以此语题之，故云脱右字也。复始祖受命而王，子孙入其元百六岁，当阳旱不生， ​此天下故灾之常也。王者受命，皆有灾会，但言夏者，举一隅小示之也。不生，物无生者也。灾其惟以人轨年除轨数，筭尽则厄也。甲乙为饥，丙丁为旱，率如此也。○按据注则正文应有「夏」字，疑「复」即「夏」之讹也。贤子继世而立，有灾方来，豫畜而待之，此所谓转祸为福。天灾虽至，万民无饥寒之色。 ​按以上疑亦坤灵图注文而混错在此者。冬温伤藏，日月不明，四时失序，万民散失，有受者常寒作藏也。霜 ​按此处原阙一字。深也，温，赏予也。雨不时，特妄赏赐也。霜不时，杀无罪。风不时，令妄出也。冬不冰，行春令，免有罪也。春冻不解，行冬令，执无罪也。西风至，作威也。南风至，免有罪也。北风至，执无罪。 ​皆谓卦之不效逆四时。夏升阳降温，三过度，雨为败。 ​谓九三、上九也。当征而遇过度，其败宜为风也。坎初六冬至，广莫风，九二小寒，六三大寒，六四立春，条风，九五雨水，上六惊蛰。震初九春分，明庶风，六二清明，六三榖雨，九四立夏。温风，六五小满，上六芒种。离初九夏至。景风，六二小暑，九三大暑，九四立秋。凉风至，六五处暑，上九白露。兑初九秋分，阊阖风霜下，九二寒露，六三霜降，九四立冬，始冰。不周风，九五小雪，上六大雪也。 ​",-1)])])}const h=t(r,[["render",c]]);export{f as __pageData,h as default};
